    """Generate documentation for the design"""
    doc_content = f"""# {design['name']}

## Description
{design['description']}

## Type
{design['type']}

## Source Files
"""
    for f in source_files:
        doc_content += f"- `{f}`\\n"

    doc_content += f"""
## Repository
- **URL**: {REPO_URL}
- **Path**: {design['source'] if isinstance(design['source'], str) else ', '.join(design['source'])}

## Interface
This design extends the Blaze Task class and implements the compute() method.

## Implementation Details
"""

    # Try to parse source for additional details
    try:
        src_file = os.path.join(design_path, source_files[0])
        with open(src_file, 'r') as f:
            content = f.read()

        # Extract class name
        class_match = re.search(r'class\\s+(\\w+)\\s*:\\s*public\\s+Task', content)
        if class_match:
            doc_content += f"- **Class Name**: {class_match.group(1)}\\n"

        # Count inputs
        task_constructor = re.search(r'Task\\((\\d+)\\)', content)
        if task_constructor:
            doc_content += f"- **Number of Inputs**: {task_constructor.group(1)}\\n"

        # Extract compute logic summary
        if 'getInput' in content:
            doc_content += "- **Input Access**: Uses getInput() and getOutput() methods\\n"
        if 'for' in content:
            loop_count = content.count('for (')
            doc_content += f"- **Loop Count**: {loop_count} loop(s)\\n"

    except Exception as e:
        doc_content += f"- Parse error: {e}\\n"

    doc_content += """
## Notes
This design is part of the Blaze accelerator framework and requires the Blaze runtime for execution.

## Generated
This documentation was automatically generated by HLSFactory.
"""

