This design is part of the Blaze accelerator framework and requires the Blaze runtime for execution.

## Generated
This documentation was automatically generated by HLSFactory.
"""

    doc_path = os.path.join(design_path, "README.md")
    with open(doc_path, 'w') as f:
        f.write(doc_content)

    return "README.md"

def compile_design(design, design_path, source_files):
    """Compile the design and record results"""
    compile_log = []

    # Find the main source file (not the testbench)
    main_sources = [f for f in source_files if f != "testbench.cpp" and not f.endswith('.cl')]

    for src in main_sources:
        src_path = os.path.join(design_path, src)

        # Create a simple compilation test
        compile_cmd = [
            "clang", "-c", "-fsyntax-only",
            "-I" + STUBS_PATH,
            "-I" + os.path.join(REPO_PATH, "manager/include"),
            "-I" + os.path.join(REPO_PATH, "manager/include/blaze"),
            "-std=c++11",
            src_path
        ]

        compile_log.append(f"Compiling: {src}")
        compile_log.append(f"Command: {' '.join(compile_cmd)}")

        try:
            result = subprocess.run(
                compile_cmd,
                capture_output=True,
                text=True,
                timeout=30
            )

            if result.returncode == 0:
                compile_log.append(f"Result: SUCCESS")
            else:
                compile_log.append(f"Result: FAILED (return code {result.returncode})")
                if result.stderr:
                    compile_log.append(f"STDERR:\\n{result.stderr}")
                if result.stdout:
                    compile_log.append(f"STDOUT:\\n{result.stdout}")

        except subprocess.TimeoutExpired:
            compile_log.append("Result: TIMEOUT")
        except Exception as e:
            compile_log.append(f"Result: ERROR - {e}")

        compile_log.append("-" * 50)

    # Also try to compile testbench
    tb_path = os.path.join(design_path, "testbench.cpp")
    if os.path.exists(tb_path):
        compile_cmd = [
            "clang", "-c", "-fsyntax-only",
            "-I" + STUBS_PATH,
            "-I" + os.path.join(REPO_PATH, "manager/include"),
            "-I" + os.path.join(REPO_PATH, "manager/include/blaze"),
            "-std=c++11",
            tb_path
        ]

        compile_log.append(f"Compiling: testbench.cpp")
        compile_log.append(f"Command: {' '.join(compile_cmd)}")

        try:
            result = subprocess.run(
                compile_cmd,
                capture_output=True,
                text=True,
                timeout=30
            )

            if result.returncode == 0:
                compile_log.append(f"Result: SUCCESS")
            else:
                compile_log.append(f"Result: FAILED (return code {result.returncode})")
                if result.stderr:
                    compile_log.append(f"STDERR:\\n{result.stderr}")

        except Exception as e:
            compile_log.append(f"Result: ERROR - {e}")

        compile_log.append("-" * 50)

    # Write compile log
    log_path = os.path.join(design_path, "compile_log.txt")
    with open(log_path, 'w') as f:
        f.write('\\n'.join(compile_log))

    return "compile_log.txt"

def generate_tcl_script(design, design_path):
    """Generate TCL synthesis script for Vivado HLS"""

    tcl_content = f"""# Vivado HLS TCL Script for {design['name']}
# Auto-generated by HLSFactory

set design_name "{design['name']}"
set top_func "compute"

# Create project
open_project -reset $design_name

# Add source files
"""

    # Add source files
    sources = [f for f in os.listdir(design_path) if f.endswith(('.cpp', '.c', '.h', '.hpp')) and f != "testbench.cpp"]
    for src in sources:
        tcl_content += f'add_files "{src}"\\n'

    # Add testbench
    tcl_content += f'add_files -tb "testbench.cpp"\\n'

    tcl_content += f"""
# Set top function
set_top $top_func

# Create solution
open_solution -reset "solution1"

# Set device (default to Xilinx xc7z020)
set_part {{xc7z020clg484-1}}

# Create clock
create_clock -period 10 -name default

# Run C simulation
csim_design

# Run C synthesis
csynth_design

# Export design
export_design -format ip_catalog

# Close project
close_project

puts "HLS synthesis completed for $design_name"
"""

    tcl_path = os.path.join(design_path, "synthesize.tcl")
    with open(tcl_path, 'w') as f:
        f.write(tcl_content)

    return "synthesize.tcl"

def process_design(design):
    """Process a single design through the pipeline"""
    print(f"\\nProcessing design: {design['name']}")

    # Step 1: Create folder
    design_path = create_design_folder(design)
    print(f"  Created folder: {design_path}")

    # Step 2: Copy source files
    source_files = copy_source_files(design, design_path)
    print(f"  Copied files: {source_files}")

    # Step 3: Generate testbench
    tb_file = generate_testbench(design, design_path)
    print(f"  Generated testbench: {tb_file}")

    # Step 4: Generate documentation
    doc_file = generate_documentation(design, design_path, source_files)
    print(f"  Generated documentation: {doc_file}")

    # Step 5: Compile design
    log_file = compile_design(design, design_path, source_files + [tb_file])
    print(f"  Compilation log: {log_file}")

    # Step 6: Generate TCL script
    tcl_file = generate_tcl_script(design, design_path)
    print(f"  Generated TCL script: {tcl_file}")

    return {
        "name": design["name"],
        "type": design["type"],
        "files": source_files + [tb_file, doc_file, log_file, tcl_file]
    }

def generate_manifest(all_designs_info):
    """Generate final manifest"""
    manifest = {
        "repository": {
            "url": REPO_URL,
            "name": "blaze",
            "path": REPO_PATH
        },
        "output_path": OUTPUT_PATH,
        "total_designs": len(all_designs_info),
        "designs": all_designs_info
    }

    manifest_path = os.path.join(OUTPUT_PATH, "manifest.json")
    with open(manifest_path, 'w') as f:
        json.dump(manifest, f, indent=2)

    print(f"\\nGenerated manifest: {manifest_path}")
    return manifest_path

def main():
    print("HLSFactory Pipeline")
    print("=" * 50)
    print(f"Repository: {REPO_URL}")
    print(f"Output: {OUTPUT_PATH}")
    print(f"Stubs: {STUBS_PATH}")

    # Process all designs
    all_designs_info = []
    for design in DESIGNS:
