        all_designs_info.append(info)

    # Generate manifest
    generate_manifest(all_designs_info)

    print("\\n" + "=" * 50)
    print("Pipeline completed successfully!")
    print(f"Total designs processed: {len(all_designs_info)}")

if __name__ == "__main__":
    main()
